<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import AuthGate from './AuthGate.vue'
import AccountPanel from './AccountPanel.vue'
import CalendarPanel from './CalendarPanel.vue'
import HistoryPanel from './HistoryPanel.vue'
import TodoistSetup from './TodoistSetup.vue'
import { useAuthStore } from './stores/auth'
import { useWorkspaceStore } from './stores/workspace'
import type { Dependency, Task } from './types'
import { barWidth, civilDayOffset } from './utils/timeline'
import { virtualWindow } from './utils/virtual-window'
const store=useWorkspaceStore(); const auth=useAuthStore(); const needsTodoist=ref(false); const syncState=ref('unknown'); const syncDiagnostics=ref(false),syncInfo=ref<{lastSyncedAt:string|null;error:string|null;pending:number;conflicts:number}>({lastSyncedAt:null,error:null,pending:0,conflicts:0}); const appearance=ref(false), textScale=ref<'compact'|'comfortable'|'large'>('comfortable'), spacing=ref<'compact'|'comfortable'|'spacious'>('comfortable'); let eventSource:EventSource|null=null; let eventReconnect:ReturnType<typeof setTimeout>|null=null
const csrfHeaders=():Record<string,string>=>{const token=document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;return token?{'X-CSRF-TOKEN':token}:{}}
function connectEvents(){eventSource?.close();eventSource=new EventSource('/api/v1/events');eventSource.addEventListener('workspace.updated',async()=>{await store.load();syncState.value=store.workspace?.project.sync_status??syncState.value});eventSource.onerror=()=>{eventSource?.close();eventReconnect=setTimeout(connectEvents,5000)}}
let initializedUserId:string|null=null
async function loadSyncStatus(){const response=await fetch('/api/v1/todoist/status',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Não foi possível verificar a conexão com o Todoist.');const status=await response.json();syncState.value=status.sync_state??status.integration_status??'unknown';syncInfo.value={lastSyncedAt:status.last_synced_at??null,error:status.last_sync_error??null,pending:status.pending_operations??0,conflicts:status.conflict_operations??0};return status}
async function initializeWorkspace(){if(!auth.user||initializedUserId===auth.user.id)return;initializedUserId=auth.user.id;try{const status=await loadSyncStatus();needsTodoist.value=!status.connected||!status.project;if(!needsTodoist.value){await store.load();syncState.value=store.workspace?.project.sync_status??syncState.value}connectEvents()}catch(error){needsTodoist.value=true;toast.value=error instanceof Error?error.message:'Não foi possível carregar sua configuração.'}}
watch(()=>auth.user?.id,()=>{if(auth.user)initializeWorkspace();else{initializedUserId=null;eventSource?.close()}})
onMounted(async()=>{const savedText=localStorage.getItem('ganttist.text-scale'),savedSpacing=localStorage.getItem('ganttist.spacing');if(savedText==='compact'||savedText==='comfortable'||savedText==='large')textScale.value=savedText;if(savedSpacing==='compact'||savedSpacing==='comfortable'||savedSpacing==='spacious')spacing.value=savedSpacing;await auth.bootstrap();await initializeWorkspace()})
onUnmounted(()=>{eventSource?.close();if(eventReconnect)clearTimeout(eventReconnect)})
watch([textScale,spacing],()=>{localStorage.setItem('ganttist.text-scale',textScale.value);localStorage.setItem('ganttist.spacing',spacing.value)})
const drawer=ref(false), notices=ref(false), filters=ref(false), account=ref(false), calendarPanel=ref(false), historyPanel=ref(false), projectMenu=ref(false), projectLoading=ref(false), projects=ref<{id:string;name:string}[]>([]), simulating=ref(false), creating=ref(false), newTaskTitle=ref(''), deleting=ref(false), preserveContinuity=ref(true), deletionPreview=ref<{incoming:unknown[];outgoing:unknown[];continuity:unknown[]}|null>(null), toast=ref(''), scrollTop=ref(0), scrollLeft=ref(0), timelineViewport=ref(1000), timelineElement=ref<HTMLElement|null>(null), simulation=ref<{command_id:string;changes:{task_id:string;start:string;finish:string}[]}|null>(null), pendingIntent=ref<{taskId:string;start:string;finish:string|null}|null>(null), operationIntent=ref<{taskId:string;start:string;finish:string|null}|null>(null), operation=ref<{operation_id:string;state:string;error?:string|null;items:{state:string}[]}|null>(null)
const dependencyTarget=ref(''), dependencyType=ref<'FS'|'SS'|'FF'|'SF'>('FS'), dependencyConfirmation=ref<{action:'add'|'remove';id?:string;from?:string;to?:string;type?:string}|null>(null)
const drag=ref<{taskId:string;mode:'move'|'left'|'right';originX:number;start:string;finish:string}|null>(null)
const taskDraft=ref<Task|null>(null)
const activeTask=computed(()=>taskDraft.value??store.workspace?.tasks.find(t=>t.id===store.selected.at(-1)) ?? null)
const syncLabel=computed(()=>({synced:'Sincronizado',degraded:'Sincronização pendente',reauthorization_required:'Reconexão necessária',unknown:'Verificando sincronização'} as Record<string,string>)[syncState.value]??'Sincronização pendente')
const timelineStart=computed(()=>{const dates=(store.workspace?.tasks??[]).flatMap(task=>[task.start,task.finish,task.virtual_start].filter((date):date is string=>date!==null&&date!==undefined)).sort();const start=new Date((dates[0]??new Date().toISOString().slice(0,10))+'T12:00:00');start.setDate(start.getDate()-14);return start})
const timelineEnd=computed(()=>{const dates=(store.workspace?.tasks??[]).flatMap(task=>[task.start,task.finish,task.virtual_start].filter((date):date is string=>date!==null&&date!==undefined)).sort();const end=new Date((dates.at(-1)??new Date().toISOString().slice(0,10))+'T12:00:00');end.setDate(end.getDate()+15);return end})
const days=computed(()=>{const r:Date[]=[];for(let d=new Date(timelineStart.value);d<timelineEnd.value;d.setDate(d.getDate()+1))r.push(new Date(d));return r})
const dayWidth=computed(()=>store.zoom==='day'?64:store.zoom==='week'?42:24)
const rowHeight=computed(()=>spacing.value==='compact'?44:spacing.value==='comfortable'?49:54)
const px=(date:string|null)=>date?civilDayOffset(timelineStart.value,new Date(date+'T12:00:00'))*dayWidth.value:0
const width=(task:Task)=>barWidth(task.start,task.finish,dayWidth.value)
const visibleTasks=computed(()=>{const all=new Map(store.tasks.map(task=>[task.id,task]));return store.tasks.filter(task=>{let parentId=task.parent_id;while(parentId){if(store.hiddenGroups.has(parentId))return false;parentId=all.get(parentId)?.parent_id}return true})})
const taskIndexes=computed(()=>new Map(visibleTasks.value.map((task,index)=>[task.id,index])))
const virtualStart=computed(()=>virtualWindow(visibleTasks.value.length,rowHeight.value,scrollTop.value,620).start)
const virtualEnd=computed(()=>virtualWindow(visibleTasks.value.length,rowHeight.value,scrollTop.value,620).end)
const renderedTasks=computed(()=>visibleTasks.value.slice(virtualStart.value,virtualEnd.value))
const visibleDayRange=computed(()=>virtualWindow(days.value.length,dayWidth.value,scrollLeft.value,timelineViewport.value,8))
const renderedDays=computed(()=>days.value.slice(visibleDayRange.value.start,visibleDayRange.value.end).map((date,offset)=>({date,index:visibleDayRange.value.start+offset})))
const rowOffset=(id:string)=>((taskIndexes.value.get(id)??0)*rowHeight.value)
const onTimelineScroll=(event:Event)=>{const target=event.target as HTMLElement;scrollTop.value=target.scrollTop;scrollLeft.value=target.scrollLeft;timelineViewport.value=target.clientWidth}
function onTableWheel(event:WheelEvent){if(!timelineElement.value)return;event.preventDefault();timelineElement.value.scrollTop+=event.deltaY}
const hiddenDependencies=computed(()=>{const visible=new Set(visibleTasks.value.map(task=>task.id));return (store.workspace?.dependencies??[]).filter(dependency=>!visible.has(dependency.from)||!visible.has(dependency.to))})
const ghostChanges=computed(()=>simulation.value?.changes.map(change=>({change,task:visibleTasks.value.find(task=>task.id===change.task_id),index:visibleTasks.value.findIndex(task=>task.id===change.task_id)})).filter(item=>item.task&&item.index>=0)??[])
const monthSegments=computed(()=>{const out:{label:string;span:number}[]=[];days.value.forEach(d=>{const label=d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});const last=out.at(-1);last?.label===label?last.span++:out.push({label,span:1})});return out})
const pathFor=(from:string,to:string)=>{const a=visibleTasks.value.findIndex(t=>t.id===from),b=visibleTasks.value.findIndex(t=>t.id===to),ft=visibleTasks.value[a],tt=visibleTasks.value[b];if(a<0||b<0||!ft?.finish||!tt?.start)return '';const x1=px(ft.finish)+dayWidth.value-6,x2=px(tt.start)+4,y1=a*rowHeight.value+rowHeight.value/2,y2=b*rowHeight.value+rowHeight.value/2,mid=x1+Math.max(18,(x2-x1)/2);return `M${x1},${y1} H${mid} V${y2} H${x2}`}
function select(task:Task,e:MouseEvent){store.toggleSelect(task.id,e.ctrlKey||e.metaKey);taskDraft.value={...task};drawer.value=true}
function toggleCheckbox(task:Task){store.toggleSelect(task.id,true)}
function rowKeydown(task:Task,event:KeyboardEvent){if(event.key==='Enter'||event.key===' '){event.preventDefault();select(task,new MouseEvent('click'))}else if(event.key==='ArrowLeft'&&(task.kind==='group'||task.has_children)){if(!store.hiddenGroups.has(task.id))store.toggleGroup(task.id)}else if(event.key==='ArrowRight'&&(task.kind==='group'||task.has_children)){if(store.hiddenGroups.has(task.id))store.toggleGroup(task.id)}}
function taskTitle(id:string){return store.workspace?.tasks.find(task=>task.id===id)?.title??id}
function revealDependency(dependency:Dependency){store.revealTask(dependency.from);store.revealTask(dependency.to);toast.value=`Relação ${dependency.type} revelada`;setTimeout(()=>toast.value='',3000)}
async function toggleProjectMenu(){projectMenu.value=!projectMenu.value;if(!projectMenu.value||projects.value.length)return;projectLoading.value=true;try{const response=await fetch('/api/v1/todoist/projects',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Não foi possível carregar os projetos do Todoist.');projects.value=(await response.json()).data}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível carregar projetos.';projectMenu.value=false;setTimeout(()=>toast.value='',3500)}finally{projectLoading.value=false}}
async function switchProject(project:{id:string;name:string}){try{const response=await fetch('/api/v1/todoist/project',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({todoist_project_id:project.id,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível trocar o projeto.');projectMenu.value=false;await store.load();toast.value=`Projeto ${project.name} selecionado`}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível trocar o projeto.'}setTimeout(()=>toast.value='',3500)}
function simulationPayload(task:Task){if(!task.start)throw new Error('Defina uma data inicial antes de simular.');const intent={taskId:task.id,start:task.start,finish:task.finish};pendingIntent.value=intent;return {commandId:crypto.randomUUID(),intent}}
async function simulate(task=activeTask.value){if(!task){toast.value='Selecione ou mova uma tarefa para simular.';setTimeout(()=>toast.value='',3500);return}simulating.value=true;simulation.value=null;try{const response=await fetch('/api/v1/schedule/simulate',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify(simulationPayload(task))});if(!response.ok)throw new Error('Não foi possível calcular o cenário.');simulation.value=(await response.json()).data;if(store.workspace?.calendar?.rescheduling_mode==='AUTOMATIC'){toast.value='Aplicando cenário automaticamente';await applySimulation()}else toast.value=`Simulação pronta: ${simulation.value?.changes.length??0} tarefa(s) seriam ajustadas`}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível calcular o cenário.'}finally{simulating.value=false;setTimeout(()=>toast.value='',3500)}}
async function watchOperation(operationId:string){const response=await fetch(`/api/v1/schedule/operations/${operationId}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Não foi possível acompanhar a operação.');operation.value=(await response.json()).data;if(['pending','applying','partial'].includes(operation.value?.state??''))setTimeout(()=>watchOperation(operationId).catch(error=>{toast.value=error instanceof Error?error.message:'Falha ao acompanhar operação.'}),1500);else await store.load()}
async function applySimulation(){if(!simulation.value||!pendingIntent.value)return;try{const intent={...pendingIntent.value};const response=await fetch('/api/v1/schedule/apply',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({commandId:simulation.value.command_id,intent})});if(!response.ok)throw new Error('Não foi possível registrar a operação.');const data=(await response.json()).data;simulation.value=null;pendingIntent.value=null;operationIntent.value=intent;operation.value={operation_id:data.operation_id,state:data.state,items:[]};await watchOperation(data.operation_id);toast.value='Operação enviada para aplicação'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível registrar a operação.'}setTimeout(()=>toast.value='',4500)}
async function recalculateConflict(){if(!operationIntent.value)return;const source=store.workspace?.tasks.find(item=>item.id===operationIntent.value?.taskId);if(!source)return;await simulate({...source,start:operationIntent.value.start,finish:operationIntent.value.finish})}
async function recoverSync(){if(syncState.value==='reauthorization_required'){needsTodoist.value=true;eventSource?.close();return}try{await store.load();await loadSyncStatus();syncState.value=store.workspace?.project.sync_status??'synced';toast.value='Sincronização atualizada'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível atualizar a sincronização.'}setTimeout(()=>toast.value='',3500)}
async function addDependency(){if(!activeTask.value||!dependencyTarget.value)return;try{const response=await fetch('/api/v1/dependencies',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({from:activeTask.value.id,to:dependencyTarget.value,type:dependencyType.value,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível criar a dependência.');await store.load();dependencyTarget.value='';toast.value='Dependência adicionada'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível criar a dependência.'}setTimeout(()=>toast.value='',4000)}
async function removeDependency(id:string){try{const response=await fetch(`/api/v1/dependencies/${id}`,{method:'DELETE',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível remover a dependência.');await store.load();toast.value='Dependência removida'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível remover a dependência.'}setTimeout(()=>toast.value='',4000)}
function requestAddDependency(){if(!activeTask.value||!dependencyTarget.value)return;dependencyConfirmation.value={action:'add',from:activeTask.value.id,to:dependencyTarget.value,type:dependencyType.value}}
function requestRemoveDependency(id:string){dependencyConfirmation.value={action:'remove',id}}
async function confirmDependency(){const confirmation=dependencyConfirmation.value;dependencyConfirmation.value=null;if(!confirmation)return;if(confirmation.action==='add')await addDependency();else if(confirmation.id)await removeDependency(confirmation.id)}
function shiftDate(value:string,daysToAdd:number){const date=new Date(value+'T12:00:00');date.setDate(date.getDate()+daysToAdd);return date.toISOString().slice(0,10)}
function startDrag(task:Task,event:PointerEvent,mode:'move'|'left'|'right'){if(!task.start||!task.finish)return;event.preventDefault();drag.value={taskId:task.id,mode,originX:event.clientX,start:task.start,finish:task.finish};window.addEventListener('pointermove',dragMove);window.addEventListener('pointerup',endDrag,{once:true})}
function dragMove(event:PointerEvent){if(!drag.value)return;const task=store.workspace?.tasks.find(item=>item.id===drag.value?.taskId);if(!task)return;const delta=Math.round((event.clientX-drag.value.originX)/dayWidth.value);if(drag.value.mode==='move'){task.start=shiftDate(drag.value.start,delta);task.finish=shiftDate(drag.value.finish,delta)}else if(drag.value.mode==='left'){task.start=shiftDate(drag.value.start,delta);if(task.start>task.finish!)task.start=task.finish}else{task.finish=shiftDate(drag.value.finish,delta);if(task.finish!<task.start!)task.finish=task.start}}
async function endDrag(){window.removeEventListener('pointermove',dragMove);const task=drag.value&&store.workspace?.tasks.find(item=>item.id===drag.value?.taskId);drag.value=null;if(task)await simulate(task)}
async function persistTask(task:Task){const csrf=document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;const response=await fetch(`/api/v1/tasks/${task.id}`,{method:'PUT',headers:{'Content-Type':'application/json',Accept:'application/json',...(csrf?{'X-CSRF-TOKEN':csrf}:{})},body:JSON.stringify({title:task.title,priority:task.priority??1,completed:task.status==='completed',commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível salvar a tarefa no Todoist.');store.updateTask(task)}
async function persistCompletionDate(task:Task){if(task.status!=='completed'||!task.effective_completion)return;const response=await fetch(`/api/v1/tasks/${task.id}/completion-date`,{method:'PUT',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({completionDate:task.effective_completion,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível salvar a data efetiva de conclusão.')}
async function createTask(){if(!newTaskTitle.value.trim())return;creating.value=true;try{const response=await fetch('/api/v1/tasks',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({title:newTaskTitle.value.trim(),commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível criar a tarefa.');newTaskTitle.value='';creating.value=false;await store.load();toast.value='Tarefa criada no Todoist'}catch(error){creating.value=false;toast.value=error instanceof Error?error.message:'Não foi possível criar a tarefa.'}setTimeout(()=>toast.value='',3500)}
async function previewDeletion(){if(!activeTask.value||activeTask.value.kind!=='task')return;try{const response=await fetch(`/api/v1/tasks/${activeTask.value.id}/deletion-preview`,{method:'POST',headers:{Accept:'application/json',...csrfHeaders()}});if(!response.ok)throw new Error('Não foi possível calcular o impacto da exclusão.');deletionPreview.value=(await response.json()).data}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível calcular o impacto.';setTimeout(()=>toast.value='',3500)}}
async function deleteTask(){if(!activeTask.value||!deletionPreview.value)return;deleting.value=true;try{const response=await fetch(`/api/v1/tasks/${activeTask.value.id}`,{method:'DELETE',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({confirmed:true,preserveContinuity:preserveContinuity.value,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível excluir a tarefa.');drawer.value=false;deletionPreview.value=null;await store.load();toast.value='Tarefa excluída'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível excluir a tarefa.'}finally{deleting.value=false;setTimeout(()=>toast.value='',3500)}}
async function saveTask(){if(!activeTask.value)return;const task={...activeTask.value},source=store.workspace?.tasks.find(item=>item.id===task.id);try{if(source&&(task.start!==source.start||task.finish!==source.finish)){await simulate(task);drawer.value=false;toast.value='Cenário calculado. Revise e aplique a operação para confirmar as datas.'}else{await persistTask(task);await persistCompletionDate(task);drawer.value=false;toast.value='Alterações salvas no Todoist'}taskDraft.value=null;setTimeout(()=>toast.value='',4500)}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível salvar as alterações';setTimeout(()=>toast.value='',4500)}}
function statusLabel(s:string){return ({completed:'Concluída',running:'Em execução',not_started:'Não iniciada',late:'Atrasada',unscheduled:'Sem data'} as Record<string,string>)[s]}
</script>

<template>
<main v-if="auth.loading" class="loading"><div class="loader-logo">G</div><p>Verificando seu acesso…</p></main>
<AuthGate v-else-if="!auth.user" :auth="auth" />
<TodoistSetup v-else-if="needsTodoist" @ready="needsTodoist=false;store.load()" />
<div v-else class="app-shell" :class="[`text-${textScale}`, `space-${spacing}`]">
  <header class="topbar">
    <div class="brand"><span class="brand-mark"><i></i><i></i><i></i></span><strong>Ganttist</strong></div>
    <div class="project-switcher"><span class="eyebrow">PROJETO TODOIST</span><button :aria-expanded="projectMenu" aria-haspopup="listbox" @click="toggleProjectMenu"><span class="project-dot"></span>{{store.workspace?.project.name||'Carregando…'}} <span class="chevron">⌄</span></button><div v-if="projectMenu" class="project-menu" role="listbox" aria-label="Projetos Todoist"><span v-if="projectLoading">Carregando projetos…</span><button v-for="project in projects" :key="project.id" role="option" :aria-selected="project.id===store.workspace?.project.id" @click="switchProject(project)">{{project.name}}</button></div></div>
    <div class="top-actions">
      <div class="appearance-wrap"><button class="icon-btn appearance-btn" aria-label="Aparência" title="Aparência" @click="appearance=!appearance">A<span>a</span></button><div v-if="appearance" class="appearance-menu"><b>Aparência</b><label>Tamanho do texto<select v-model="textScale"><option value="compact">Menor</option><option value="comfortable">Confortável</option><option value="large">Maior</option></select></label><label>Espaçamento<select v-model="spacing"><option value="compact">Compacto</option><option value="comfortable">Confortável</option><option value="spacious">Espaçoso</option></select></label></div></div>
      <button class="sync-pill" :class="syncState" :aria-label="`${syncLabel}. Abrir diagnóstico de sincronização.`" @click="syncDiagnostics=!syncDiagnostics"><span class="pulse"></span><span><b>{{syncLabel}}</b><small>{{syncState==='synced'?'dados reconciliados':syncState==='reauthorization_required'?'conectar novamente':'tentar atualizar'}}</small></span></button><section v-if="syncDiagnostics" class="sync-diagnostics" role="dialog" aria-label="Diagnóstico de sincronização"><b>{{syncLabel}}</b><span>Última reconciliação: {{syncInfo.lastSyncedAt?new Date(syncInfo.lastSyncedAt).toLocaleString('pt-BR'):'ainda não realizada'}}</span><span>Pendências: {{syncInfo.pending}} · Conflitos: {{syncInfo.conflicts}}</span><small v-if="syncInfo.error">{{syncInfo.error}}</small><button class="soft-btn" :disabled="store.refreshing" @click="recoverSync">{{syncState==='reauthorization_required'?'Reconectar':'Reconciliar agora'}}</button></section>
      <button class="icon-btn" aria-label="Notificações" @click="notices=!notices">◴<em>3</em></button>
      <button class="icon-btn" aria-label="Abrir histórico do projeto" title="Histórico" @click="historyPanel=true">≡</button>
      <button class="icon-btn" aria-label="Configurar calendário do projeto" title="Calendário" @click="calendarPanel=true">▣</button>
      <button class="avatar" aria-label="Abrir sessões e configurações da conta" :aria-expanded="account" aria-haspopup="dialog" @click="account=true">{{(auth.user.name||auth.user.email).slice(0,2).toUpperCase()}}</button>
    </div>
  </header>

  <main v-if="store.loading" class="loading"><div class="loader-logo">G</div><p>Organizando seu planejamento…</p></main>
  <main v-else-if="store.error" class="loading"><p>{{store.error}}</p><button class="primary" @click="store.load">Tentar novamente</button></main>
  <main v-else-if="store.empty" class="loading"><div><p>Este projeto ainda não possui tarefas.</p><button class="primary" :disabled="store.refreshing" @click="store.load">Atualizar projeto</button></div></main>
  <main v-else class="main">
    <section class="commandbar">
      <div class="title-block"><div><span class="eyebrow">VISÃO DE PLANEJAMENTO</span><h1>{{store.workspace?.project.name}}</h1></div><span v-if="store.workspace?.project.id==='demo-product-launch'" class="demo-badge">AMBIENTE DEMO</span></div>
      <div class="commands">
        <label class="search"><span>⌕</span><input v-model="store.search" placeholder="Buscar tarefa…"><kbd>⌘ K</kbd></label>
        <div class="segmented"><button :class="{active:store.zoom==='day'}" @click="store.zoom='day'">Dia</button><button :class="{active:store.zoom==='week'}" @click="store.zoom='week'">Semana</button><button :class="{active:store.zoom==='month'}" @click="store.zoom='month'">Mês</button></div>
        <button class="soft-btn" @click="filters=!filters">≡ Filtros <span v-if="store.statusFilter!=='all'" class="count">1</span></button>
        <button class="soft-btn" @click="creating=!creating">＋ Tarefa</button><button class="primary" @click="simulate()"><span v-if="simulating" class="spinner"></span><span v-else>✦</span> {{simulating?'Calculando…':'Simular cenário'}}</button><button v-if="simulation?.changes.length" class="soft-btn" @click="applySimulation">Aplicar {{simulation.changes.length}} alterações</button>
      </div>
    </section>

    <div v-if="creating" class="create-task" role="region" aria-label="Criar tarefa"><input v-model="newTaskTitle" placeholder="Nome da nova tarefa" @keyup.enter="createTask"><button class="soft-btn" @click="creating=false">Cancelar</button><button class="primary" :disabled="creating&& !newTaskTitle.trim()" @click="createTask">Criar no Todoist</button></div>
    <div v-if="store.selected.length" class="selection-bar" role="status"><b>{{store.selected.length}} tarefa(s) selecionada(s)</b><span>Use a seleção para comparar, revisar ou iniciar um cenário.</span><button class="soft-btn" @click="store.selected=[]">Limpar seleção</button></div>
    <div v-if="operation" class="operation-status" :class="operation.state"><b>Operação {{operation.state}}</b><span>{{operation.items.filter(item=>item.state==='applied').length}}/{{operation.items.length}} itens aplicados</span><small v-if="operation.error">{{operation.error}}</small><button v-if="operation.state==='conflict'&&operationIntent" class="soft-btn" @click="recalculateConflict">Recalcular com dados atuais</button></div>
    <section v-if="simulation" class="simulation-review" role="region" aria-label="Revisão da simulação"><div><b>Revise {{simulation.changes.length}} alteração(ões) calculada(s)</b><small>Os ghosts são apenas uma prévia. Nada será salvo antes de confirmar.</small></div><ul><li v-for="change in simulation.changes" :key="change.task_id">{{taskTitle(change.task_id)}}: {{change.start}} → {{change.finish}}</li></ul><div><button class="soft-btn" @click="simulation=null;pendingIntent=null">Descartar</button><button class="primary" @click="applySimulation">Confirmar operação</button></div></section>
    <div v-if="store.stale" class="workspace-state" role="status"><span>Exibindo o último estado conhecido; a atualização remota falhou.</span><button class="soft-btn" :disabled="store.refreshing" @click="store.load">{{store.refreshing?'Atualizando…':'Tentar novamente'}}</button></div>
    <section class="stats-row">
      <article><span class="stat-icon violet">◔</span><div><small>PROGRESSO GERAL</small><b>{{store.workspace?.stats.progress}}%</b></div><div class="mini-progress"><i :style="{width:store.workspace?.stats.progress+'%'}"></i></div></article>
      <article><span class="stat-icon green">✓</span><div><small>CONCLUÍDAS</small><b>{{store.workspace?.stats.completed}} <em>/ {{store.workspace?.stats.total}}</em></b></div><span class="trend">+2 esta semana</span></article>
      <article><span class="stat-icon coral">⌁</span><div><small>CAMINHO CRÍTICO</small><b>{{store.workspace?.stats.critical}} <em>tarefas</em></b></div><span class="risk">ATENÇÃO</span></article>
      <article><span class="stat-icon amber">○</span><div><small>SEM PLANEJAMENTO</small><b>{{store.workspace?.stats.unscheduled}} <em>tarefa</em></b></div><button @click="store.statusFilter='unscheduled'">Revisar →</button></article>
    </section>

    <div v-if="filters" class="filter-popover"><b>Filtrar por estado</b><button v-for="f in [['all','Todas'],['running','Em execução'],['completed','Concluídas'],['unscheduled','Sem data']]" :class="{active:store.statusFilter===f[0]}" @click="store.statusFilter=f[0]">{{f[1]}}</button></div>

    <section class="gantt-card">
      <div class="gantt-head-left"><span>TAREFA</span><span>RESP.</span><span>STATUS</span></div>
      <div class="timeline-head">
        <div class="months" :style="{width:days.length*dayWidth+'px',transform:`translateX(${-scrollLeft}px)`}"><span v-for="m in monthSegments" :style="{width:m.span*dayWidth+'px'}">{{m.label}}</span></div>
        <div class="day-heads"><span v-for="day in renderedDays" :class="{weekend:[0,6].includes(day.date.getDay()),today:day.date.toISOString().slice(0,10)===new Date().toISOString().slice(0,10)}" :style="{width:dayWidth+'px',left:(day.index*dayWidth-scrollLeft)+'px'}"><b>{{day.date.toLocaleDateString('pt-BR',{weekday:'short'}).slice(0,3)}}</b>{{day.date.getDate()}}</span></div>
      </div>
      <div class="rows-left" role="tree" aria-label="Hierarquia de tarefas" @wheel="onTableWheel">
        <div v-for="task in renderedTasks" :key="task.id" class="task-row" role="treeitem" :aria-level="task.level+1" :aria-expanded="task.kind==='group'||task.has_children?!store.hiddenGroups.has(task.id):undefined" tabindex="0" :class="[{group:task.kind==='group',parent:task.has_children,selected:store.selected.includes(task.id),'calendar-inconsistent':task.calendar_inconsistent},task.status]" :style="{height:rowHeight+'px',top:rowOffset(task.id)-scrollTop+'px'}" @click="select(task,$event)" @keydown="rowKeydown(task,$event)">
          <div class="task-name" :style="{paddingLeft:(task.level*24+14)+'px'}"><input class="task-check" type="checkbox" :checked="store.selected.includes(task.id)" :aria-label="`Selecionar ${task.title}`" @click.stop @change="toggleCheckbox(task)"><button v-if="task.kind==='group'||task.has_children" class="collapse" @click.stop="store.toggleGroup(task.id)">{{store.hiddenGroups.has(task.id)?'›':'⌄'}}</button><span v-else class="status-dot"></span><div><b>{{task.title}}</b><small v-if="task.kind==='task'">#{{task.id.toUpperCase()}} · P{{task.priority}}</small></div></div>
          <div><span v-if="task.assignee" class="mini-avatar">{{task.assignee}}</span><span v-else>—</span></div>
          <div><span v-if="task.calendar_inconsistent" class="calendar-warning" title="A data cai em dia não útil; simule para corrigir">Calendário</span><span v-else class="status-label"><i></i>{{statusLabel(task.status)}}</span></div>
        </div>
      </div>
      <div ref="timelineElement" class="timeline-scroll" @scroll="onTimelineScroll">
        <div class="timeline-body" :style="{width:days.length*dayWidth+'px',height:visibleTasks.length*rowHeight+'px'}">
          <div v-for="day in renderedDays" class="day-column" :class="{weekend:[0,6].includes(day.date.getDay())}" :style="{left:day.index*dayWidth+'px',width:dayWidth+'px'}"></div>
          <div class="today-line" :style="{left:px(new Date().toISOString().slice(0,10))+'px'}"><span>HOJE</span></div>
          <svg class="dependencies" :width="days.length*dayWidth" :height="visibleTasks.length*rowHeight"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6Z"/></marker><marker id="arrow-critical" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6Z"/></marker></defs><path v-for="dep in store.workspace?.dependencies" :d="pathFor(dep.from,dep.to)" :class="{critical:dep.critical}" marker-end="url(#arrow)"/></svg>
          <div v-for="ghost in ghostChanges" :key="ghost.change.task_id" class="task-ghost" :style="{left:px(ghost.change.start)+'px',top:ghost.index*rowHeight+14+'px',width:barWidth(ghost.change.start,ghost.change.finish,dayWidth)+'px'}"><span>Prévia</span></div>
          <div v-for="task in renderedTasks" class="bar-lane" :style="{top:rowOffset(task.id)+'px',height:rowHeight+'px'}">
            <div v-if="task.start" class="task-bar" :class="[task.kind,task.status,{critical:task.critical,parent:task.has_children,'calendar-inconsistent':task.calendar_inconsistent}]" :style="{left:px(task.start)+'px',width:width(task)+'px'}" @click.stop="select(task,$event)" @pointerdown.stop="startDrag(task,$event,'move')">
              <template v-if="task.kind==='group'"><i class="group-line"></i><i class="group-left"></i><i class="group-right"></i></template>
              <template v-else><i class="progress-fill" :style="{width:task.progress+'%'}"></i><span class="bar-label">{{task.title}} <small v-if="task.progress">{{task.progress}}%</small></span><i class="handle left" @pointerdown.stop="startDrag(task,$event,'left')"></i><i class="handle right" @pointerdown.stop="startDrag(task,$event,'right')"></i></template>
            </div>
            <div v-else class="unscheduled-chip"><span>＋</span> Definir data</div>
          </div>
        </div>
      </div>
      <div class="gantt-footer"><span><i class="legend running"></i> Em execução</span><span><i class="legend critical"></i> Caminho crítico</span><span><i class="legend completed"></i> Concluída</span><span><i class="legend unscheduled"></i> Sem data</span><div class="footer-right">Fuso: América/São Paulo · Dias úteis visíveis <button>?</button></div></div>
    </section>
  </main>

    <section v-if="hiddenDependencies.length" class="hidden-dependencies" aria-live="polite">
      <div><b>Relações ocultas pelos filtros ou recolhimento</b><p>Elas continuam ativas no planejamento e no cálculo do caminho crítico.</p></div>
      <ul><li v-for="dependency in hiddenDependencies" :key="dependency.id"><span :class="{critical:dependency.critical}">{{taskTitle(dependency.from)}} → {{taskTitle(dependency.to)}} ({{dependency.type}})</span><button @click="revealDependency(dependency)">Revelar</button></li></ul>
    </section>
  <aside class="drawer" :class="{open:drawer&&activeTask}"><template v-if="activeTask"><header><div><span class="eyebrow">DETALHES DA TAREFA</span><h2>{{activeTask.title}}</h2></div><button @click="drawer=false">×</button></header><div class="drawer-body"><div class="source-line"><span class="todoist-mark">✓</span><div><b>Sincronizada com Todoist</b><small>Campos nativos são atualizados na origem</small></div></div><label>Título<input v-model="activeTask.title"></label><div class="form-grid"><label>Data inicial<input v-model="activeTask.start" type="date"></label><label>Data final<input v-model="activeTask.finish" type="date"></label></div><label>Estado<select v-model="activeTask.status"><option value="not_started">Não iniciada</option><option value="running">Em execução</option><option value="completed">Concluída</option></select></label><label v-if="activeTask.status==='completed'">Data efetiva de conclusão <small>Override próprio; não reabre a tarefa no Todoist.</small><input v-model="activeTask.effective_completion" type="date"></label><div class="dependency-box"><div><span>⌁</span><b>Dependências</b></div><p>Esta tarefa participa de {{store.workspace?.dependencies.filter(d=>d.from===activeTask?.id||d.to===activeTask?.id).length}} relações de precedência.</p><div v-for="dependency in store.workspace?.dependencies.filter(d=>d.from===activeTask?.id||d.to===activeTask?.id)" :key="dependency.id" class="dependency-item"><span>{{dependency.from===activeTask?.id?'→':'←'}} {{dependency.type}}</span><button @click="requestRemoveDependency(dependency.id)">Remover</button></div><div class="dependency-form"><select v-model="dependencyTarget"><option value="">Outra tarefa…</option><option v-for="task in store.tasks.filter(t=>t.kind==='task'&&t.id!==activeTask?.id)" :key="task.id" :value="task.id">{{task.title}}</option></select><select v-model="dependencyType"><option value="FS">FS</option><option value="SS">SS</option><option value="FF">FF</option><option value="SF">SF</option></select><button @click="requestAddDependency">Adicionar</button></div><section v-if="dependencyConfirmation" class="dependency-confirm" role="alert"><b>{{dependencyConfirmation.action==='add'?'Confirmar nova dependência':'Remover dependência?'}}</b><p v-if="dependencyConfirmation.action==='add'">{{taskTitle(dependencyConfirmation.from!)}} → {{taskTitle(dependencyConfirmation.to!)}} ({{dependencyConfirmation.type}}). O core validará escopo e ciclo antes de persistir.</p><p v-else>A relação será removida do planejamento.</p><div><button class="soft-btn" @click="dependencyConfirmation=null">Cancelar</button><button class="primary" @click="confirmDependency">Confirmar</button></div></section></div><section v-if="deletionPreview" class="delete-preview" role="alert"><b>Excluir esta tarefa?</b><p>{{deletionPreview.incoming.length}} entrada(s), {{deletionPreview.outgoing.length}} saída(s) e {{deletionPreview.continuity.length}} ligação(ões) de continuidade possíveis.</p><label><input v-model="preserveContinuity" type="checkbox"> Preservar continuidade (FS)</label><div><button class="soft-btn" @click="deletionPreview=null">Cancelar</button><button class="danger-btn" :disabled="deleting" @click="deleteTask">{{deleting?'Excluindo…':'Confirmar exclusão'}}</button></div></section></div><footer><button v-if="activeTask.kind==='task'&&!deletionPreview" class="danger-btn" @click="previewDeletion">Excluir</button><button class="soft-btn" @click="drawer=false">Cancelar</button><button class="primary" @click="saveTask">Salvar alterações</button></footer></template></aside>
  <div v-if="drawer" class="scrim" @click="drawer=false"></div>
  <div v-if="toast" class="toast"><span>✓</span>{{toast}}</div>
</div>
<AccountPanel :open="account" @close="account=false" @deleted="account=false;auth.logout()" />
<CalendarPanel :open="calendarPanel" @close="calendarPanel=false" @saved="calendarPanel=false;store.load()" />
<HistoryPanel :open="historyPanel" @close="historyPanel=false" />
</template>
